@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('[data-order-form]'),b=f?.querySelector('[data-sale-items]');if(!f||!b)return;const p=f.querySelector('[data-sale-entry-product]'),stock=f.querySelector('[data-sale-entry-stock]'),qty=f.querySelector('[data-sale-entry-qty]'),price=f.querySelector('[data-sale-entry-price]'),total=f.querySelector('[data-sale-entry-total]'),error=f.querySelector('[data-sale-entry-error]');let editing=null;const money=n=>'Rs '+Number(n||0).toLocaleString(),sync=()=>{const o=p.selectedOptions[0];stock.value=o?.dataset.stock?`${o.dataset.stock} ${o.dataset.unit||''}`:'';price.value=o?.dataset.price||'';total.value='Rs '+((Number(qty.value)||0)*(Number(price.value)||0)).toLocaleString()},rows=()=>[...b.querySelectorAll('[data-order-line]')],render=()=>{rows().forEach((r,i)=>{r.querySelector('[data-index]').textContent=i+1;r.querySelectorAll('[name]').forEach(x=>x.name=x.name.replace(/products\[\d+\]/,`products[${i}]`))});b.querySelector('[data-sale-empty]')?.classList.toggle('d-none',rows().length>0);window.updateOrderPreview?.()},reset=()=>{editing=null;p.value='';qty.value=1;price.value='';stock.value='';total.value='Rs 0.00';error.classList.add('d-none');window.syncTradeFlowTomSelect?.(p);setTimeout(()=>window.getTradeFlowTomSelect?.(p)?.focus(),0)},add=()=>{const o=p.selectedOptions[0],q=Number(qty.value),s=Number(o?.dataset.stock||0);if(!p.value||q<1||q>s){error.textContent=!p.value?'Select a product.':`Insufficient stock. Only ${s} units are available.`;error.classList.remove('d-none');return}const r=editing||document.createElement('tr');r.dataset.orderLine='';r.dataset.price=price.value;r.innerHTML=`<td data-index></td><td>${o.text}<input type="hidden" name="products[0][id]" value="${p.value}"></td><td>${qty.value}<input type="hidden" name="products[0][quantity]" value="${qty.value}" data-order-qty max="${s}"></td><td>Rs ${Number(price.value).toLocaleString()}</td><td>Rs 0.00</td><td>Rs 0.00</td><td>Rs ${(q*Number(price.value)).toLocaleString()}</td><td><button type="button" class="btn btn-sm btn-outline-primary" data-edit-sale-item>Edit</button></td><td><button type="button" class="btn btn-sm btn-outline-danger" data-delete-sale-item>Delete</button></td>`;if(!editing)b.appendChild(r);render();reset()};p.addEventListener('change',sync);qty.addEventListener('input',sync);f.querySelector('[data-add-sale-item]').addEventListener('click',add);b.addEventListener('click',e=>{const r=e.target.closest('[data-order-line]');if(!r)return;if(e.target.closest('[data-delete-sale-item]')){if(editing===r)reset();r.remove();render()}if(e.target.closest('[data-edit-sale-item]')){editing=r;p.value=r.querySelector('[name$="[id]"]').value;qty.value=r.querySelector('[data-order-qty]').value;window.syncTradeFlowTomSelect?.(p);sync();window.getTradeFlowTomSelect?.(p)?.focus()}});f.addEventListener('submit',e=>{if(rows().length)return;e.preventDefault();error.textContent='Add at least one sale item before creating the order.';error.classList.remove('d-none');window.getTradeFlowTomSelect?.(p)?.focus()});sync();render()});</script>@endpush
